InterfaceAsPlainText.xhtml:
PROGRAM MAIN VAR
i: INT;
END_VAR

ST.xhtml:
IF stDashBoard.bRunning THEN
stGlobal.fEmergencyPressure:=stGlobal.fEmergencyPressure +0.01 ; 
stDashboard.fSpeedActual:=stDashboard.fSpeedActual+0.04 ;
stDashboard.fTemperature := stDashboard.fTemperature +0.05;
stCarriage.fActPosition := stCarriage.fActPosition +0.07;
stCarriage.fActVelocity := stCarriage.fActVelocity +0.07;
stMold.fClampingPressure:= stMold.fClampingPressure +0.08;
stMold.fMoldTemperature:= stMold.fMoldTemperature +0.09;
ELSE
stGlobal.fEmergencyPressure:=stGlobal.fEmergencyPressure -0.01 ; ;
stDashboard.fSpeedActual:=stDashboard.fSpeedActual-0.03 ;
stDashboard.fTemperature := stDashboard.fTemperature -0.04;
stCarriage.fActPosition := stCarriage.fActPosition -0.05;
stCarriage.fActVelocity := stCarriage.fActVelocity -0.06;
stMold.fClampingPressure:= stMold.fClampingPressure -0.07;
stMold.fMoldTemperature:= stMold.fMoldTemperature -0.08;
END_IF

IF bCmdReset THEN
stDashboard.fSpeedActual:=0.0 ;
stDashboard.fTemperature := 0.0;
stCarriage.fActPosition := 0.0;
stCarriage.fActVelocity := 0.0;
stMold.fClampingPressure:= 0.0;
stMold.fMoldTemperature:= 0.0 ;
END_IF
GVL_HMI.stGlobal.Alarms[1];
GVL_HMI.stGlobal.Alarms[3];
GVL_HMI.stGlobal.Alarms[5];
IF GVL_HMI.stGlobal.bAlarmReset THEN
	FOR i:=0 TO 250  DO
	 GVL_HMI.stGlobal.Alarms[i]:=FALSE;	
	END_FOR
END_IF

